 /* ===== Nav dropdown ===== */
 document.querySelectorAll('.nav-dropdown-btn').forEach(btn => {
   const panel = btn.nextElementSibling;

   btn.addEventListener('click', () => {
     const expanded = btn.getAttribute('aria-expanded') === 'true';
     btn.setAttribute('aria-expanded', String(!expanded));
     if (expanded) {
       panel.hidden = true;
     } else {
       panel.hidden = false;
     }
   });

   btn.addEventListener('keydown', e => {
     if (e.key === 'Escape') {
       btn.setAttribute('aria-expanded', 'false');
       panel.hidden = true;
       btn.focus();
     }
   });

   document.addEventListener('click', e => {
     if (!btn.parentElement.contains(e.target)) {
       btn.setAttribute('aria-expanded', 'false');
       panel.hidden = true;
     }
   });
 });

 /* ===== Wishlist toggle ===== */
 document.querySelectorAll('.product-wishlist').forEach(btn => {
   btn.addEventListener('click', () => {
     const pressed = btn.getAttribute('aria-pressed') === 'true';
     btn.setAttribute('aria-pressed', String(!pressed));
   });
 });

 /* ===== Add to cart ===== */
 const cartStatus = document.getElementById('cart-status');
 const cartCountEl = document.getElementById('cart-count');
 let cartCount = 0;

 function showCartStatus(message) {
   cartStatus.textContent = message;
   cartStatus.classList.add('visible');
   clearTimeout(cartStatus._timer);
   cartStatus._timer = setTimeout(() => {
     cartStatus.classList.remove('visible');
   }, 3000);
 }

 document.querySelectorAll('[data-add-to-cart]').forEach(btn => {
   btn.addEventListener('click', () => {
     const name = btn.dataset.addToCart;
     cartCount++;
     cartCountEl.textContent = cartCount;
     cartCountEl.removeAttribute('hidden');
     // Update cart button accessible label
     document.getElementById('cart-btn').setAttribute(
       'aria-label',
       `Shopping cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`
     );
     showCartStatus(`"${name}" added to cart`);
   });
 });

 /* ===== Countdown timers ===== */
 document.querySelectorAll('[data-countdown]').forEach(el => {
   let remaining = parseInt(el.dataset.countdown, 10);

   const update = () => {
     const h = Math.floor(remaining / 3600);
     const m = Math.floor((remaining % 3600) / 60);
     const s = remaining % 60;
     const formatted = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
     el.querySelector('strong').textContent = formatted;
     if (remaining > 0) remaining--;
   };

   update();
   setInterval(update, 1000);
 });

 /* ===== Mobile menu ===== */
 const mobileMenuBtn = document.getElementById('mobile-menu-btn');
 const mobileNav = document.getElementById('mobile-nav');

 if (mobileMenuBtn && mobileNav) {
   mobileMenuBtn.addEventListener('click', () => {
     const expanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';
     mobileMenuBtn.setAttribute('aria-expanded', String(!expanded));
     mobileNav.hidden = expanded;
   });

   document.addEventListener('keydown', e => {
     if (e.key === 'Escape' && mobileMenuBtn.getAttribute('aria-expanded') === 'true') {
       mobileMenuBtn.setAttribute('aria-expanded', 'false');
       mobileNav.hidden = true;
       mobileMenuBtn.focus();
     }
   });
 }

